import static org.mockito.Mockito.*;

public class FitnessFunction_value_TriageGen2Test {

    private CMAESOptimizer optimizerSpy;
    private CMAESOptimizer.FitnessFunction fitnessFunction;
    private double[] testPoint;

    @Before
    public void setUp() {
        // Since FitnessFunction is an inner class of CMAESOptimizer, 
        // we need to mock the outer class to control computeObjectiveValue
        optimizerSpy = Mockito.spy(new CMAESOptimizer(1e-4, 1e-4, null, null, null, null, null, null));
        fitnessFunction = optimizerSpy.new FitnessFunction();
        testPoint = new double[]{1.0, 2.0};
    }

    /**
     * Test Case 1: Standard mode (boundaries == null)
     * Covers: else branch, isMinimize = true
     */
    @Test
    public void testValue_NoBoundaries_Minimize() throws Exception {
        // Use reflection to set private fields if they are not accessible via constructor
        setField(fitnessFunction, "boundaries", null);
        setField(fitnessFunction, "isRepairMode", false);
        setField(fitnessFunction, "isMinimize", true);

        // Mock decode to return a specific array
        double[] decoded = new double[]{0.5, 0.5};
        when(optimizerSpy.decode(testPoint)).thenReturn(decoded);
        when(optimizerSpy.computeObjectiveValue(decoded)).thenReturn(10.0);

        double result = fitnessFunction.value(testPoint);

        assertEquals(10.0, result, 1e-9);
        verify(optimizerSpy, times(1)).computeObjectiveValue(decoded);
    }

    /**
     * Test Case 2: Standard mode (boundaries == null), isMinimize = false
     * Covers: else branch, isMinimize = false
     */
    @Test
    public void testValue_NoBoundaries_Maximize() throws Exception {
        setField(fitnessFunction, "boundaries", null);
        setField(fitnessFunction, "isRepairMode", false);
        setField(fitnessFunction, "isMinimize", false);

        double[] decoded = new double[]{0.5, 0.5};
        when(optimizerSpy.decode(testPoint)).thenReturn(decoded);
        when(optimizerSpy.computeObjectiveValue(decoded)).thenReturn(10.0);

        double result = fitnessFunction.value(testPoint);

        assertEquals(-10.0, result, 1e-9);
    }

    /**
     * Test Case 3: Repair mode (boundaries != null && isRepairMode is true)
     * Covers: if branch, isMinimize = true
     */
    @Test
    public void testValue_WithRepair_Minimize() throws Exception {
        double[] boundaries = new double[]{0.0, 1.0};
        double[] repairedPoint = new double[]{0.0, 1.0};
        double[] decodedRepaired = new double[]{0.1, 0.1};
        double[] decodedOriginal = new double[]{0.5, 0.5};

        setField(fitnessFunction, "boundaries", boundaries);
        setField(fitnessFunction, "isRepairMode", true);
        setField(fitnessFunction, "isMinimize", true);

        // Mocking the internal calls via the spy
        // We must mock the repair method which is likely in the outer class or fitness function
        // Based on the provided code, repair(point) is called.
        doReturn(repairedPoint).when(fitnessFunction).repair(testPoint);

        when(fitnessFunction.decode(repairedPoint)).thenReturn(decodedRepaired);
        when(optimizerSpy.computeObjectiveValue(decodedRepaired)).thenReturn(5.0);

        // Mock penalty method
        doReturn(2.0).when(fitnessFunction).penalty(testPoint, repairedPoint);

        double result = fitnessFunction.value(testPoint);

        // value = computeObjectiveValue(decode(repaired)) + penalty(point, repaired)
        // value = 5.0 + 2.0 = 7.0
        assertEquals(7.0, result, 1e-9);
    }

    /**
     * Test Case 4: Repair mode (isRepairMode is false even if boundaries exist)
     * Covers: else branch (boundary check fails)
     */
    @Test
    public void testValue_BoundariesExistButNoRepairMode_Minimize() throws Exception {
        setField(fitnessFunction, "boundaries", new double[]{0.0, 1.0});
        setField(fitnessFunction, "isRepairMode", false);
        setField(fitnessFunction, "isMinimize", true);

        when(fitnessFunction.decode(testPoint)).thenReturn(testPoint);
        when(optimizerSpy.computeObjectiveValue(testPoint)).thenReturn(15.0);

        double result = fitnessFunction.value(testPoint);

        assertEquals(15.0, result, 1e-9);
        verify(fitnessFunction, never()).repair(any());
    }

    /**
     * Test Case 5: Repair mode (boundaries is null but isRepairMode is true)
     * Covers: else branch (boundary null check)
     */
    @Test
    public void testValue_BoundariesNullButRepairModeTrue_Minimize() throws Exception {
        setField(fitnessFunction, "boundaries", null);
        setField(fitnessFunction, "isRepairMode", true);
        setField(fitnessFunction, "isMinimize", true);

        when(fitnessFunction.decode(testPoint)).thenReturn(testPoint);
        when(optimizerSpy.computeObjectiveValue(testPoint)).thenReturn(20.0);

        double result = fitnessFunction.value(testPoint);

        assertEquals(20.0, result, 1e-9);
        verify(fitnessFunction, never()).repair(any());
    }

    // Helper method to access private fields of the inner class via reflection
    private void setField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
